package com.bank.queue.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "pending_payments")
public class PendingPayment {
    @Id @Column(name = "payment_id") private String paymentId;
    @Column(name = "account_id") private String accountId;
    private BigDecimal amount;
    private String status;
    @Version private Long version;  // OPTIMISTIC LOCKING
    @Column(name = "locked_by") private String lockedBy;
    @Column(name = "processed_at") private LocalDateTime processedAt;

    protected PendingPayment() {}

    public void process(String processor) {
        this.status = "PROCESSED";
        this.lockedBy = processor;
        this.processedAt = LocalDateTime.now();
    }

    public String getPaymentId() { return paymentId; }
    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
    public String getStatus() { return status; }
    public Long getVersion() { return version; }
}
