// SKIP LOCKED: concurrent queue processing without deadlocks
package com.bank.queue.service;

import com.bank.queue.model.PendingPayment;
import com.bank.queue.repository.PendingPaymentRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.Optional;

@Service
@RequiredArgsConstructor
@Slf4j
public class QueueProcessorService {

    private final PendingPaymentRepository paymentRepo;

    /**
     * SKIP LOCKED: pick next available payment, skip busy ones.
     *
     * Instance-1 calls this: picks PAY-001 (locks it)
     * Instance-2 calls this: PAY-001 is locked → SKIP → picks PAY-002
     * Instance-3 calls this: PAY-001, PAY-002 locked → picks PAY-003
     *
     * No deadlock. No waiting. No duplicate. Each instance processes different payments.
     */
    @Transactional
    public Optional<String> processNextPayment() {
        String processor = Thread.currentThread().getName();

        Optional<PendingPayment> next = paymentRepo.findNextPendingSkipLocked();
        if (next.isEmpty()) {
            log.info("[SKIP LOCKED] [{}] No pending payments", processor);
            return Optional.empty();
        }

        PendingPayment payment = next.get();
        log.info("[SKIP LOCKED] [{}] Processing {} Rs.{} (other instances skip this row)",
            processor, payment.getPaymentId(), payment.getAmount());

        // Simulate processing
        payment.process(processor);
        paymentRepo.save(payment);

        log.info("[SKIP LOCKED] [{}] Done: {} → PROCESSED", processor, payment.getPaymentId());
        return Optional.of(payment.getPaymentId());
    }
}
