package com.bank.queue.controller;

import com.bank.queue.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/queue")
@RequiredArgsConstructor
public class QueueController {

    private final QueueProcessorService queueProcessor;
    private final OptimisticRetryService optimisticService;

    @PostMapping("/process-next")
    public String processNext() {
        return queueProcessor.processNextPayment()
            .orElse("No pending payments");
    }

    @PostMapping("/process-optimistic/{paymentId}")
    public String processOptimistic(@PathVariable String paymentId) {
        return optimisticService.processWithOptimisticRetry(paymentId);
    }
}
