package com.bank.queue.service;

import com.bank.queue.model.PendingPayment;
import com.bank.queue.repository.PendingPaymentRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class QueueProcessorServiceTest {

    @Mock PendingPaymentRepository paymentRepo;
    @InjectMocks QueueProcessorService service;

    @Test
    void shouldProcessNextAvailablePayment() {
        PendingPayment payment = mock(PendingPayment.class);
        when(payment.getPaymentId()).thenReturn("PAY-001");
        when(payment.getAmount()).thenReturn(new java.math.BigDecimal("50000"));
        when(paymentRepo.findNextPendingSkipLocked()).thenReturn(Optional.of(payment));

        Optional<String> result = service.processNextPayment();

        assertThat(result).contains("PAY-001");
        verify(payment).process(anyString());
        verify(paymentRepo).save(payment);
    }

    @Test
    void shouldReturnEmptyWhenNoPending() {
        when(paymentRepo.findNextPendingSkipLocked()).thenReturn(Optional.empty());

        Optional<String> result = service.processNextPayment();

        assertThat(result).isEmpty();
    }
}
